# Avoid modifying the existing published curriculum names; enrich each manifest with independent sequence plans.
for num,seqs in plans.items():
    p=root/('src/content/week01.ts' if num==1 else f'src/weeks/week{num:02d}.ts')
    s=p.read_text()
    if num==1:
        # week 1 has a compact one-line export and all sequences need not be complete yet.
        import_line="import { sequenceContract } from './authoring';\n"
        s=import_line+s
        end=s.rfind('puzzles:[...core,advanced]')
        s=s[:end]+"sequences:[\n"+",\n".join(f"  sequenceContract('w{num:02d}-s{i:02d}',{title!r},{objective!r},[{','.join(repr(k) for k in kinds.split(','))}],{validator!r},{target},{adv!r})" for i,(title,objective,kinds,validator,target,adv) in enumerate(seqs,1))+"\n],"+s[end:]
    else:
        s=s.replace("import type { WeekContent } from '../core/types';", "import type { WeekContent } from '../core/types';\nimport { sequenceContract } from '../content/authoring';")
        start=s.index("  puzzles: []")
        s=s[:start]+"  sequences: [\n"+",\n".join(f"    sequenceContract('w{num:02d}-s{i:02d}',{title!r},{objective!r},[{','.join(repr(k) for k in kinds.split(','))}],{validator!r},{target},{adv!r})" for i,(title,objective,kinds,validator,target,adv) in enumerate(seqs,1))+"\n  ],\n"+s[start:]
    p.write_text(s)
# Generate independent handoff notes by week (not blank to-dos)
docs=root/'docs'/'lessons';docs.mkdir(exist_ok=True,parents=True)
for num,seqs in plans.items():
    p=(root/('src/content/week01.ts' if num==1 else f'src/weeks/week{num:02d}.ts'))
    content=f'# Week {num:02d} — Content work package\n\nSource manifest: `{p.relative_to(root)}`.\n\n**Status:** '+('Week 1 vertical slice exists; expand without breaking stable IDs.' if num==1 else 'Plan only; no runnable puzzles yet. Do not claim otherwise.')+'''\n\n## Sequences to implement\n\n| Sequence | Target micro-puzzles | Mechanics | Minimum real validator |\n|---|---:|---|---|\n'''
    for title,objective,kinds,validator,target,advanced in seqs:content+=f'| {title} | {target} | {kinds} | {validator} |\n'
    content+='\n## Educational outcomes & advanced branches\n\n'
    for title,objective,kinds,validator,target,advanced in seqs:content+=f'- **{title}:** {objective}. *Advanced branch:* {advanced}.\n'
    content+='''\n## Acceptance criteria\n\n1. Puzzle mechanics must use the shared engine and declare stable `wNN-*` IDs, sequence names matching the manifest, learning objectives, and hints without answer leaks.\n2. Any numeric/model outcome must be validated from a real implementation, not a narrative claim or random guess. Use shared deterministic fixtures and seeded variants.\n3. Sequence order should be Discover → Explain → Apply, with connected evolving workspaces when useful and independent transfer puzzles.\n4. Add unit tests for correct/incorrect answers, all procedural seeds, edge cases, XP once, skip-to-solved mastery, and inaccessible future chapters.\n5. Do not mark this week playable until all its required puzzles are independently verifiable and the entire sequence has been tested on a phone-sized viewport.\n6. Keep the curriculum fixed; no server dependency, mandatory timer, leaderboard, or generative-AI grading.\n'''
    (docs/f'week{num:02d}.md').write_text(content)
print('Generated:',len(plans),'week packages',sum(len(x) for x in plans.values()),'sequence plans',sum(sum(row[4] for row in x) for x in plans.values()),'planned puzzle targets')
